        Rnd262v.Route route = (Rnd262v row, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.Select(partitionOf(row), ownedPath, pool, out allocation);
        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd262v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd262v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd262v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd262v)row);
        public void Dispose() => writer.Dispose();
    }
}